// GET /api/super-admin/reports
//
// Report Center catalogue + previously generated reports.
// Nothing is generated by a GET: generation is an explicit, audited POST.

import { NextResponse } from 'next/server';
import { db } from '@/lib/db';
import { withAuth, type AuthContext } from '@/lib/auth-middleware';
import { requireSuperAdminOrActing } from '@/lib/super-admin/access';
import { unavailable, jsonObject, safeRows } from '@/lib/super-admin/http';
import { REPORT_CATALOG } from '@/lib/super-admin/reports';

export const dynamic = 'force-dynamic';

async function handleGet(_request: Request, auth: AuthContext) {
  const guard = requireSuperAdminOrActing(auth);
  if (!guard.ok) return guard.response;

  try {
    const generated = await safeRows<{
      id: string; reportCode: string; category: string; title: string; format: string;
      status: string; rowCount: number; generatedBy: string; generatedAt: Date; expiresAt: Date | null;
      downloadCount: number; filters: string;
    }>(
      () => db.report.findMany({
        orderBy: { generatedAt: 'desc' },
        take: 100,
        select: {
          id: true, reportCode: true, category: true, title: true, format: true, status: true,
          rowCount: true, generatedBy: true, generatedAt: true, expiresAt: true, downloadCount: true, filters: true,
        },
      }),
    );

    const categories = [...new Set(REPORT_CATALOG.map((report) => report.category))].sort();

    return NextResponse.json({
      success: true,
      catalogue: REPORT_CATALOG.map((report) => ({
        key: report.key,
        name: report.name,
        category: report.category,
        description: report.description,
        filters: report.filters,
      })),
      categories,
      totals: {
        reportTypes: REPORT_CATALOG.length,
        categories: categories.length,
        generated: generated.length,
      },
      generated: generated.map((row) => ({
        id: row.id,
        reportCode: row.reportCode,
        category: row.category,
        title: row.title,
        format: row.format,
        status: row.status,
        rowCount: row.rowCount,
        generatedBy: row.generatedBy,
        generatedAt: row.generatedAt.toISOString(),
        expiresAt: row.expiresAt?.toISOString() || null,
        downloadCount: row.downloadCount,
        filters: jsonObject(row.filters),
      })),
    });
  } catch (error) {
    return unavailable('super-admin/reports GET', error);
  }
}

export const GET = withAuth(handleGet);
